orchestration_path = (
    f"abfss://odw-config@{storage_account}"
    "orchestration/orchestration_service_bus.json"
)


def load_orchestration_entities() -> list:
    orchestration_text = (
        spark.read
        .text(orchestration_path, wholetext=True)
        .first()
        .value
    )

    orchestration = json.loads(orchestration_text)

    return [
        entity
        for entity in orchestration.get("entities", [])
        if entity.get("processing_enabled") is True
        and entity.get("run_raw_to_std") is True
    ]


def resolve_entities(entities_json: str) -> list:
    if entities_json:
        pipeline_entities = json.loads(entities_json)

        if all(
            isinstance(entity, str)
            for entity in pipeline_entities
        ):
            orchestration_entities = (
                load_orchestration_entities()
            )

            orchestration_lookup = {
                entity["entity_name"]: entity
                for entity in orchestration_entities
            }

            resolved_entities = []

            for entity_name in pipeline_entities:
                if entity_name not in orchestration_lookup:
                    raise ValueError(
                        f"Entity '{entity_name}' passed from "
                        f"pipeline was not found in "
                        f"orchestration config"
                    )

                resolved_entities.append(
                    orchestration_lookup[entity_name]
                )

            return resolved_entities

        return pipeline_entities

    return load_orchestration_entities()


entities = resolve_entities(entities_json)

print(f"Found {len(entities)} entities to process")

if not entities:
    print(
        "No enabled entities found for "
        "raw-to-standardised processing"

invalid_entities = [
    entity.get("entity_name", "<missing>")
    for entity in entities
    if not entity.get("entity_name")
]

if invalid_entities:
    error_message = (
        f"Invalid orchestration entries, "
        f"missing entity_name: {invalid_entities}"
    )

    logError(error_message)
    raise ValueError(error_message)

def format_and_log_error(
    step_name: str,
    e: Exception
) -> str:
    try:
        error_message = (
            f"[{step_name}] "
            f"{type(e).__name__}: {str(e)}"
        )[:800]

    except Exception as format_error:
        error_message = (
            f"[{step_name}] Failed to format original exception: "
            f"{type(format_error).__name__}: {str(format_error)}"
        )[:800]

    try:
        logError(error_message)

    except Exception as log_error:
        print(f"Primary logging failed: {log_error}")
        print(error_message)

    return error_message

def get_watermark(entity_name: str):
    try:
        wm_row = spark.sql(
            f"""
            SELECT MAX(last_ingest_time) AS wm_ts
            FROM odw_meta_db.service_bus_watermarks
            WHERE entity = '{entity_name}'
              AND source = 'service-bus'
            """
        ).collect()

        if wm_row and wm_row[0][0]:
            return str(wm_row[0][0])

        return None

    except Exception as e:
        print(
            f"Watermark table not accessible for {entity_name}; "
            f"processing all RAW records: {str(e)[:200]}"
        )

        return None

def create_spark_schema(entity_name: str):
    schema_output = mssparkutils.notebook.run(
        "/py_create_spark_schema",
        30,
        {
            "db_name": "odw_standardised_db",
            "entity_name": entity_name
        }
    )

    schema_json = (
        json.loads(schema_output)
        if schema_output
        else {}
    )

    if schema_json.get("schema"):
        return StructType.fromJson(
            json.loads(schema_json["schema"])
        )

    return ""

def read_raw_messages(
    source_path: str,
    last_ingest_time,
    entity_name: str,
    watermark_column: str,
    spark_schema
) -> DataFrame:
    reader = (
        spark.read
        .option("multiline", "true")
        .option("recursiveFileLookup", "true")
    )

    if last_ingest_time:
        try:
            wm_dt = datetime.strptime(
                last_ingest_time[:19],
                "%Y-%m-%d %H:%M:%S"
            )

            buffer_dt = wm_dt - timedelta(days=1)

            modified_after_str = buffer_dt.strftime(
                "%Y-%m-%dT%H:%M:%S"
            )

            reader = reader.option(
                "modifiedAfter",
                modified_after_str
            )

        except Exception as parse_err:
            print(
                f"Could not parse watermark for {entity_name}; "
                f"reading all files: {parse_err}"
            )

    if spark_schema:
        reader = reader.schema(spark_schema)

    try:
        df = reader.json(source_path)

    except Exception as e:
        print(
            f"No files found or error reading {source_path} "
            f"for {entity_name}: {e}"
        )

        return (
            spark.createDataFrame(
                [],
                schema=spark_schema
            )
            if spark_schema
            else spark.createDataFrame(
                [],
                StructType()
            )
        )

    df = df.withColumns(
        {
            "expected_from": F.current_timestamp(),
            "expected_to": F.expr(
                "current_timestamp() + INTERVAL 1 DAY"
            ),
            "ingested_datetime": F.to_timestamp(
                watermark_column
            ),
            "input_file": F.input_file_name()
        }
    )

    return df

